function isValidCardNumber(input) {
  if (typeof input !== 'string') {
    return false;
  }

  // Remove spaces and hyphens, but first check that no other invalid characters exist
  let cleaned = '';
  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (ch === ' ' || ch === '-') {
      continue;
    }
    if (ch >= '0' && ch <= '9') {
      cleaned += ch;
    } else {
      return false;
    }
  }

  if (cleaned.length < 12 || cleaned.length > 19) {
    return false;
  }

  let sum = 0;
  let doubleIt = false;

  // Process from right to left
  for (let i = cleaned.length - 1; i >= 0; i--) {
    let digit = parseInt(cleaned[i], 10);

    if (doubleIt) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    doubleIt = !doubleIt;
  }

  return sum % 10 === 0;
}

