function render(template, data) {
  if (typeof template !== 'string') {
    throw new TypeError('template must be a string');
  }

  // Regex to find placeholders: {{, optional whitespace, path, optional whitespace, }}
  // Path segments are sequences of chars not including {, }, ., whitespace
  // A valid path must have at least one segment.
  const placeholderRegex = /\{\{(\s*)([^\s{.}]+(?:\.[^\s{.}]+)*)(\s*)\}\}/g;

  return template.replace(placeholderRegex, (match, startSpace, pathStr, endSpace) => {
    // Split path into segments
    const segments = pathStr.split('.');

    // Validate path: must have at least one segment, and each segment must be non-empty
    if (segments.length === 0 || segments.some(s => s.length === 0)) {
      return match; // Invalid path, leave as is
    }

    let current = data;
    let valid = true;

    for (const segment of segments) {
      // Check if current is an object (not null) and has own property for segment
      if (current === null || typeof current !== 'object') {
        valid = false;
        break;
      }
      if (!Object.prototype.hasOwnProperty.call(current, segment)) {
        valid = false;
        break;
      }
      current = current[segment];
    }

    if (!valid || current === null || current === undefined) {
      return '';
    }

    return String(current);
  });
}

module.exports = { render };
