def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a str")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            j = i + 1
            while j < n:
                if line[j] == '"':
                    # Check for doubled quote
                    if j + 1 < n and line[j + 1] == '"':
                        j += 2  # Skip the doubled quote
                    else:
                        # End of quoted field
                        break
                else:
                    j += 1
            else:
                # Never found closing quote
                raise ValueError("Unclosed quoted field")

            # j is now at the closing quote
            # Extract the content between i+1 and j-1
            content = line[i + 1 : j]
            # Replace doubled quotes with single quotes
            content = content.replace('""', '"')
            fields.append(content)

            # After closing quote, must be comma or end of line
            if j + 1 < n and line[j + 1] != ',':
                raise ValueError("Invalid character after quoted field")
            i = j + 1  # Move past the closing quote and comma (if any)
        else:
            # Unquoted field: scan until comma or end
            j = i
            while j < n and line[j] != ',':
                j += 1
            fields.append(line[i:j])
            i = j + 1  # Move past the comma

    return fields
