  const resultMonth = resultDate.getUTCMonth() + 1;
  const resultDay = resultDate.getUTCDate();

  const y = resultYear.toString().padStart(4, '0');
  const m = resultMonth.toString().padStart(2, '0');
  const d = resultDay.toString().padStart(2, '0');

  return `${y}-${m}-${d}`;
}

