  const month = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  if (isNaN(year) || isNaN(month) || isNaN(day)) {
    throw new RangeError('Invalid date format');
  }

  // Basic validation for month and day
  if (month < 1 || month > 12) {
    throw new RangeError('Invalid month');
  }

  // Days per month for non-leap year
  const daysInMonth = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  // Check for leap year
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
  if (isLeap) {
    daysInMonth[2] = 29;
  }

  if (day < 1 || day > daysInMonth[month]) {
    throw new RangeError('Invalid day for the given month and year');
  }

  // Create a Date object (using UTC to avoid timezone issues with time components)
  // We set hours to 0, minutes to 0, seconds to 0, milliseconds to 0
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
    throw new RangeError('Invalid date');
  }

  return date;
}

