def maze_steps(grid):
    if not grid:
        return -1

    rows = len(grid)
    cols = len(grid[0])

    # Check all rows have same length
    for row in grid:
        if len(row) != cols:
            raise ValueError("All rows must have the same length")

    # Check characters and locate S and E
    start = None
    end = None
    count_s = 0
    count_e = 0

    for r in range(rows):
        for c, ch in enumerate(grid[r]):
            if ch not in 'SE#.':
                raise ValueError(f"Invalid character: {ch}")
            if ch == 'S':
                start = (r, c)
                count_s += 1
            elif ch == 'E':
                end = (r, c)
                count_e += 1

    if count_s != 1:
        raise ValueError("There must be exactly one 'S'")
    if count_e != 1:
        raise ValueError("There must be exactly one 'E'")

    if start is None or end is None:
        return -1

    # BFS
    queue = deque([(start, 0)])
    visited = {start}

    while queue:
        (r, c), dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
