    for row in grid:
        if len(row) != cols:
            raise ValueError("All rows must have the same length")

    # Check characters and locate S and E
    start = None
    end = None
    count_s = 0
    count_e = 0

    for r in range(rows):
        for c, ch in enumerate(grid[r]):
            if ch not in 'SE#.':
                raise ValueError(f"Invalid character: {ch}")
            if ch == 'S':
                start = (r, c)
                count_s += 1
            elif ch == 'E':
                end = (r, c)
                count_e += 1

    if count_s != 1:
        raise ValueError("There must be exactly one 'S'")
    if count_e != 1:
        raise ValueError("There must be exactly one 'E'")

    if start is None or end is None:
        return -1

    # BFS
    queue = deque([(start, 0)])
    visited = {start}

    while queue:
        (r, c), dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell in 'SE.':
                        visited.add((nr, nc))
                        queue.append(((nr, nc), dist + 1))

    return -1
